Section M1.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x24 x25 x26 x27 : word).        (* [comment removed for export] *)
  Variables (m : fmem) (WK DT mtl iS nbS tlS : Z) (ws rank : list Z) (jk : list byte).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Notation HW := (WK + 1236).
  Notation TGT := (Z.min (mtl + 1) 11).
  Hypothesis HMTL : 1 <= mtl <= 12.
  Hypothesis HNS : 2 <= nbS <= 256.
  Hypothesis HTLS : 1 <= tlS <= 12.
  Hypothesis HIS : 1 <= iS <= 129.
  Hypothesis LWS : zlen ws = nbS.
  Hypothesis WSR : Forall (fun w => 0 <= w <= tlS) ws.
  Hypothesis LR : zlen rank = 13.
  Hypothesis RR : Forall (fun v => 0 <= v <= 256) rank.
  Hypothesis LJK : zlen jk = 256 - nbS.
  Hypothesis HWK : 0 < WK /\ WK + 1492 <= 2^47.
  Hypothesis HDT : 0 < DT /\ DT + 4 <= 2^47.
  Hypothesis HSP : WK + 1492 <= SP /\ SP + 176 <= 2^47.
  Hypothesis D0 : rw_cells psegs m DT [C4 (Z_to_bv 64 (mtl * 16777217))].
  Hypothesis FNT : rw_cells psegs m (SP + 64) [C4 (Z_to_bv 64 nbS); C4 (Z_to_bv 64 tlS)].
  Hypothesis HWA : u8arr psegs m HW (map (Z_to_bv 8) ws ++ jk).
  Hypothesis RKA : u32arr psegs m WK (map (Z_to_bv 64) rank).
  Hypothesis MI : mem_inv psegs m.
  Hypothesis DJD : DT + 4 <= WK \/ WK + 1492 <= DT.

  Notation WF := [(HW, HW + 256); (WK, WK + 52)].

  Lemma m1_run : forall (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x19 x20 x21 x22 x23 x28 x29 x30 x31 : word),
    (forall m2 ws' rank' tl' (y1 y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y19 y28 y29 y30 y31 : word),
       rescale ws rank nbS tlS TGT = Ok (ws', rank', tl') -> tl' <= mtl + 1 ->
       u8arr psegs m2 HW (map (Z_to_bv 8) ws' ++ jk) -> u32arr psegs m2 WK (map (Z_to_bv 64) rank') ->
       munch WF m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
       evt psegs POST (MS (mkR y1 sp gp tp y5 y6 y7 (Z_to_bv 64 WK) (Z_to_bv 64 DT) (Z_to_bv 64 iS) y11 y12 y13 y14 y15 y16
                               y17 (Z_to_bv 64 HW) y19 (Z_to_bv 64 nbS) (Z_to_bv 64 nbS) (Z_to_bv 64 (mtl * 16777217))
                               (Z_to_bv 64 tl') x24 x25 x26 x27 y28 y29 y30 y31)
                          F (Z_to_bv 64 0x13558) fc None m2 (seg_rom psegs))) ->
    (forall (y1 y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y20 y21 y22 y23 y28 y29 y30 y31 : word),
       rescale ws rank nbS tlS TGT = Ok (ws, rank, tlS) -> mtl + 1 < tlS ->
       evt psegs POST (MS (mkR y1 sp gp tp y5 y6 y7 (Z_to_bv 64 WK) (Z_to_bv 64 DT) (Z_to_bv 64 iS) y11 y12 y13 y14 y15 y16
                               y17 (Z_to_bv 64 HW) (Z_to_bv 64 (-44)) y20 y21 y22 y23 x24 x25 x26 x27 y28 y29 y30 y31)
                          F (Z_to_bv 64 0x139f0) fc None m (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 WK) (Z_to_bv 64 DT) (Z_to_bv 64 iS) x11 x12 x13 x14 x15 x16
                            x17 (Z_to_bv 64 HW) (Z_to_bv 64 (-44)) x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
